const cfg = $item(0).$node['Config'].json || {};
const dryRun = !!cfg.defaultDryRun;
const locationId = String(cfg.locationId || '').trim();
const apiBaseUrl = String(cfg.apiBaseUrl || 'https://services.leadconnectorhq.com').replace(/\/$/, '');
const apiKey = String(cfg.apiKey || '').trim();
const queueTag = String(cfg.queueTag || 'Enrollment Queue - Cannabis Ads').trim();
const senderFieldName = String(cfg.senderFieldName || 'marketing_sender_email').trim();
const warmupWeek = Math.max(1, Math.trunc(Number(cfg.warmupWeekOverride || 1)));

if (!locationId) throw new Error('Missing locationId');
if (!dryRun && !apiKey) throw new Error('Missing apiKey in live mode');

let senders = [];
try { senders = JSON.parse(String(cfg.sendersJson || '[]')); } catch (e) { throw new Error('Invalid sendersJson'); }
senders = senders.filter(s => s && s.active !== false && s.email).map((s) => ({
  email: String(s.email).toLowerCase().trim(),
  weight: Math.max(1, Math.trunc(Number(s.weight || 1))),
  cap: warmupWeek <= 1 ? Number(s.capWeek1 || 50) : warmupWeek === 2 ? Number(s.capWeek2 || 75) : Number(s.capWeek3 || 100),
}));
if (!senders.length) throw new Error('No active senders');

const candidates = $items('Fetch Cold Candidates').map(i => i.json || {});
const inflight = $items('Estimate InFlight Due Today').map(i => i.json || {});
const inflightMap = new Map(inflight.map(r => [String(r.sender_email || '').toLowerCase(), Number(r.due_today || 0)]));

const minSafety = Math.max(1, Math.trunc(Number(cfg.minSafetyBuffer || 5)));
const pctSafety = Number(cfg.safetyBufferPct || 0.1);
for (const s of senders) {
  const safety = Math.max(minSafety, Math.round(s.cap * pctSafety));
  s.remaining = Math.max(0, s.cap - Number(inflightMap.get(s.email) || 0) - safety);
  s.safetyBuffer = safety;
  s.inFlightDueToday = Number(inflightMap.get(s.email) || 0);
}

const ring = [];
for (const s of senders) for (let i = 0; i < s.weight; i++) ring.push(s.email);
let idx = 0;
function pickSender() {
  for (let i = 0; i < ring.length; i++) {
    const email = ring[idx % ring.length]; idx++;
    const s = senders.find(x => x.email === email);
    if (s && s.remaining > 0) { s.remaining -= 1; return s.email; }
  }
  return '';
}

async function doHttpRequest(options) {
  if (typeof $httpRequest === 'function') return await $httpRequest(options);
  if (this?.helpers?.httpRequest) return await this.helpers.httpRequest(options);
  throw new Error('HTTP helper not available');
}
const headers = { Authorization: `Bearer ${apiKey}`, Version: '2021-07-28', 'Content-Type': 'application/json', Accept: 'application/json' };
async function apiRequest(method, path, body) {
  const options = { method, url: `${apiBaseUrl}${path}`, headers, json: true };
  if (body !== undefined) options.body = body;
  try { const data = await doHttpRequest.call(this, options); return { ok: true, data }; }
  catch (err) { return { ok: false, data: err?.response?.body || err?.message || err }; }
}

let senderFieldId = '';
if (!dryRun) {
  const cf = await apiRequest.call(this, 'GET', `/locations/${locationId}/customFields?model=contact`);
  if (!cf.ok) throw new Error(`Failed custom fields lookup: ${JSON.stringify(cf.data)}`);
  const arr = Array.isArray(cf.data?.customFields) ? cf.data.customFields : Array.isArray(cf.data?.data?.customFields) ? cf.data.data.customFields : Array.isArray(cf.data?.data) ? cf.data.data : [];
  senderFieldId = arr.find(f => String(f?.name || '').trim() === senderFieldName)?.id || '';
  if (!senderFieldId) throw new Error(`Missing GHL field: ${senderFieldName}`);
}

const runId = `${new Date().toISOString()}__sender_release`;
const out = [];
for (const c of candidates) {
  const sender = pickSender();
  if (!sender) { out.push({ json: { status: 'deferred_no_capacity', apollo_row_id: c.apollo_row_id, email: c.email } }); continue; }
  const email = String(c.email || '').trim();
  if (!email) { out.push({ json: { status: 'skipped_missing_email', apollo_row_id: c.apollo_row_id } }); continue; }

  if (dryRun) {
    out.push({ json: { status: 'planned', apollo_row_id: c.apollo_row_id, email, sender_email: sender } });
    continue;
  }

  const upsert = await apiRequest.call(this, 'POST', '/contacts/upsert', { locationId, email, firstName: c.first_name || undefined, lastName: c.last_name || undefined, phone: c.phone || undefined, companyName: c.company_name || undefined });
  if (!upsert.ok) { out.push({ json: { status: 'error_upsert', email, sender_email: sender, details: upsert.data } }); continue; }
  const contactId = upsert.data?.contact?.id || upsert.data?.id || upsert.data?.contactId || '';
  if (!contactId) { out.push({ json: { status: 'error_contact_id', email, sender_email: sender, details: upsert.data } }); continue; }

  const cfObj = { [senderFieldId]: sender };
  const setField = await apiRequest.call(this, 'PUT', `/contacts/${contactId}`, { locationId, customField: cfObj });
  if (!setField.ok) { out.push({ json: { status: 'error_set_sender', email, sender_email: sender, contact_id: contactId, details: setField.data } }); continue; }

  const tag = await apiRequest.call(this, 'POST', `/contacts/${contactId}/tags`, { tags: [queueTag] });
  if (!tag.ok) { out.push({ json: { status: 'error_add_queue_tag', email, sender_email: sender, contact_id: contactId, details: tag.data } }); continue; }

  const rowId = Number(c.apollo_row_id || 0);
  const esc = (v) => String(v || '').replace(/'/g, "''");
  const insertSql = `INSERT INTO "ColdOutreach_Release_Log" (apollo_row_id, contact_email, ghl_contact_id, sender_email, release_date, release_ts, status, run_id) VALUES (${rowId || 'NULL'}, '${esc(email)}', '${esc(contactId)}', '${esc(sender)}', CURRENT_DATE, NOW(), 'queued', '${esc(runId)}') ON CONFLICT (apollo_row_id) DO NOTHING;`;
  out.push({ json: { status: 'queued', apollo_row_id: c.apollo_row_id, email, sender_email: sender, contact_id: contactId, insertSql } });
}

out.push({ json: {
  status: 'summary',
  summary: {
    ok: true, dryRun, runId, warmupWeek,
    candidates: candidates.length,
    planned: out.filter(x => x.json.status === 'planned').length,
    queued: out.filter(x => x.json.status === 'queued').length,
    deferred: out.filter(x => x.json.status === 'deferred_no_capacity').length,
    errors: out.filter(x => String(x.json.status || '').startsWith('error_')).length,
    senders: senders.map(s => ({ email: s.email, cap: s.cap, inFlightDueToday: s.inFlightDueToday, safetyBuffer: s.safetyBuffer, remainingAfterPlan: s.remaining }))
  }
}});
return out;
